<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';
$ctx=rxp_context($pdo);rxp_require_perm($ctx,'reports');[$invScope,$invParams]=rxp_invoice_scope($ctx,'ix');$clauses=["EXISTS(SELECT 1 FROM invoice ix WHERE ix.id_invoice=p.id_invoice AND $invScope)"];$params=$invParams;if($ctx['bot_tokens']){[$ph,$tp]=rxp_in($ctx['bot_tokens']);$clauses[]="p.bottype IN ($ph)";$params=array_merge($params,$tp);}$scope='('.implode(' OR ',$clauses).')';$status=trim((string)($_GET['status']??''));$where=$scope;$pp=$params;if($status!==''){$where.=' AND p.payment_Status=?';$pp[]=$status;}$page=max(1,(int)($_GET['p']??1));$per=50;$off=($page-1)*$per;$q=$pdo->prepare("SELECT COUNT(*) FROM Payment_report p WHERE $where");$q->execute($pp);$total=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT p.* FROM Payment_report p WHERE $where ORDER BY p.id DESC LIMIT $per OFFSET $off");$q->execute($pp);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
rxp_layout_start($ctx,'پرداخت‌ها','payments.php');?>
<div><h1 class="rxp-title">پرداخت‌ها</h1><div class="rxp-sub"><?=$total?> تراکنش متعلق به مشتریان محدوده شما</div></div><div class="rxp-card"><form method="get" class="rxp-form"><div class="rxp-field"><label>وضعیت</label><select name="status"><option value="">همه</option><?php foreach(['paid','waiting','reject','expire'] as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><button class="rxp-btn">فیلتر</button></form></div><div class="rxp-card"><div class="rxp-table-wrap"><table class="rxp-table"><thead><tr><th>کد</th><th>مشتری</th><th>مبلغ</th><th>روش</th><th>وضعیت</th><th>زمان</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><code><?=rxp_h($r['id_order'])?></code></td><td><a href="users.php?id=<?=urlencode((string)$r['id_user'])?>"><?=rxp_h($r['id_user'])?></a></td><td><?=rxp_money($r['price'])?></td><td><?=rxp_h($r['Payment_Method'])?></td><td><span class="rxp-badge"><?=rxp_h($r['payment_Status'])?></span></td><td><?=rxp_h($r['time'])?></td></tr><?php endforeach;?></tbody></table></div><?php rxp_pager($page,(int)ceil($total/$per),['status'=>$status]);?></div><?php rxp_layout_end();
